use serde_json::json;
use ulw_loop_core::quality_gate::validate_quality_gate;
use ulw_loop_core::surface::UlwLoopToolkitSurface;
fn gate()->serde_json::Value{json!({"codeReview":{"by":"lazycodex-code-reviewer","recommendation":"APPROVE","codeQualityStatus":"CLEAR","reportPath":"code-review.md","evidence":"review","blockers":[]},"manualQa":{"by":"lazycodex-qa-executor","status":"passed","evidence":"qa","surfaceEvidence":[{"id":"s","criterionRef":"C1","surface":"cli","invocation":"true","verdict":"passed","artifactRefs":["a"]}],"adversarialCases":[{"id":"adv","criterionRef":"C1","scenario":"role validation","expectedBehavior":"reject swapped roles","verdict":"passed","artifactRefs":["a"]}],"artifactRefs":[{"id":"a","kind":"cli-transcript","description":"a","path":"qa.txt"}]},"gateReview":{"by":"lazycodex-gate-reviewer","recommendation":"APPROVE","reportPath":"gate-review.md","evidence":"review","blockers":[]},"iteration":{"fullRerun":true,"status":"passed","rerunCommands":["test"],"evidence":"rerun"},"criteriaCoverage":{"totalCriteria":2,"passCount":2,"originalIntent":"i","desiredOutcome":"d","userOutcomeReview":"u","adversarialClassesCovered":[]}})}
#[test]fn arbitrary_roles_rejected(){for (s,k) in [("codeReview","senior"),("manualQa","qa-person"),("gateReview","release")]{let mut g=gate();g[s]["by"]=json!(k);assert!(validate_quality_gate(&g,None).unwrap_err().message.contains(&format!("{s}.by")));}}
#[test]fn senpi_roles_accepted(){let mut g=gate();g.as_object_mut().unwrap().remove("codeReview");g["manualQa"]["by"]=json!("main-session");g["gateReview"]["by"]=json!("category:deep");assert!(validate_quality_gate(&g,Some(&ulw_loop_core::quality_gate::ValidateQualityGateOptions{repo_root:None,fs:None,current_attempt_dir:None,reviewer_surface:Some(UlwLoopToolkitSurface::OmoSenpi)})).is_ok());}
#[test]fn senpi_code_review_rejected(){let e=validate_quality_gate(&gate(),Some(&ulw_loop_core::quality_gate::ValidateQualityGateOptions{repo_root:None,fs:None,current_attempt_dir:None,reviewer_surface:Some(UlwLoopToolkitSurface::OmoSenpi)})).unwrap_err();assert!(e.message.contains("no codeReview lane"));}
#[test]fn lazycodex_four_section_gate_optional_code_review(){let mut g=gate();g.as_object_mut().unwrap().remove("codeReview");g["criteriaCoverage"]["adversarialClassesCovered"]=json!(["arbitrary_role","swapped_role"]);assert!(validate_quality_gate(&g,None).is_ok());}
#[test]fn swapped_senpi_roles_rejected(){let mut g=gate();g.as_object_mut().unwrap().remove("codeReview");g["manualQa"]["by"]=json!("category:deep");g["gateReview"]["by"]=json!("main-session");let e=validate_quality_gate(&g,Some(&ulw_loop_core::quality_gate::ValidateQualityGateOptions{repo_root:None,fs:None,current_attempt_dir:None,reviewer_surface:Some(UlwLoopToolkitSurface::OmoSenpi)})).unwrap_err();assert!(e.message.contains("manualQa.by"));}
#[test]fn swapped_lazycodex_roles_rejected(){for (s,k) in [("codeReview","lazycodex-qa-executor"),("manualQa","lazycodex-gate-reviewer"),("gateReview","lazycodex-code-reviewer")]{let mut g=gate();g[s]["by"]=json!(k);assert!(validate_quality_gate(&g,None).unwrap_err().message.contains(&format!("{s}.by")));}}
